def keep_existing_behaviour(apps, schema_editor):
    """Existing connections keep doing what they did: one without
    organization import put every device in its own organization, so it is
    single-customer. Existing links count as automatic matches, which the
    reconciliation command re-checks; nothing is unlinked here."""
    RMMConnection = apps.get_model('integrations', 'RMMConnection')
    RMMDevice = apps.get_model('integrations', 'RMMDevice')
    RMMConnection.objects.filter(import_organizations=False).update(customer_scope='single')
    RMMConnection.objects.filter(import_organizations=True).update(customer_scope='multi')
    RMMDevice.objects.filter(linked_asset__isnull=False).update(link_status='auto')
    RMMDevice.objects.filter(data_refreshed_at__isnull=True).update(
        data_refreshed_at=models.F('last_synced_at'))


